SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.NAME AS oblname, Имена_станций.ordnumb, Станции2019.Year, Станции2019.NUST, Станции2019.nr, Станции2019.E, Станции2019.EOTP, Станции2019.EURT, Станции2019.EUST, Станции2019.Q, Станции2019.TURT, Станции2019.TUST, Станции2019.B, Станции2019.GAZ, Доп_угли2019.gazpp, Станции2019.MAZUT, Станции2019.TORF, Станции2019.SLAN, Станции2019.PROCH, Доп_угли2019.koksdom, Доп_угли2019.prochgaz, Доп_угли2019.tvproch, Станции2019.UGOL, Станции2019.DON, Станции2019.PODM, Станции2019.PECH, Доп_угли2019.intin, Доп_угли2019.vork, Станции2019.ARKT, Станции2019.KUZN, Доп_угли2019.kuzngd, Доп_угли2019.kuznt, Доп_угли2019.kuznss, Доп_угли2019.kuznun, Станции2019.URAL, Доп_угли2019.sver, Доп_угли2019.chel, Доп_угли2019.kizel, Станции2019.BASHK, Станции2019.KAZAH, Доп_угли2019.ekib, Доп_угли2019.maikub, Станции2019.KARAG, Станции2019.KAN, Доп_угли2019.nazar, Доп_угли2019.ibor, Доп_угли2019.berez, Доп_угли2019.per, Доп_угли2019.irbei, Доп_угли2019.kansk, Станции2019.TUNG, Доп_угли2019.jer, Доп_угли2019.karab, Станции2019.IRKUT, Доп_угли2019.azey, Доп_угли2019.mug, Доп_угли2019.cher, Станции2019.HAK, Станции2019.TUV, Станции2019.BUR, Доп_угли2019.gusin, Доп_угли2019.tugn, Доп_угли2019.okino, Станции2019.CHIT, Доп_угли2019.har, Доп_угли2019.urt, Доп_угли2019.tataur, Доп_угли2019.tarbag, Доп_угли2019.zab_kam, Станции2019.YAKUT, Доп_угли2019.neru, Доп_угли2019.zyryan, Доп_угли2019.pyak, Станции2019.AMUR, Доп_угли2019.rai, Доп_угли2019.erk, Станции2019.URG, Станции2019.USHUM, Станции2019.PRIM, Доп_угли2019.bikin, Доп_угли2019.razdol, Доп_угли2019.hankai, Станции2019.MAG, Станции2019.SAH, Станции2019.KAMCH, Станции2019.CHUKOT, Доп_угли2019.anad, Доп_угли2019.bering, Станции2019.QOTR, Станции2019.SNK, Станции2019.EWTP, Станции2019.NT, Станции2019.OBOR, Станции2019.VED, Станции2019.OBL, Станции2019.DEP, Станции2019.OES, Станции2019.ER, Станции2019.NUMB1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм, Имена_станций.GK, Станции2019.BE, имена_ГК.name AS namegk, имена_БЕ.name AS namebe, Города.Name AS Town, IIf([obor]=20 Or [obor]=90,"ГТУ",IIf([obor]=21 Or [obor]=91,"ПГУ",IIf([obor]=22,"Диз",IIf([obor]=23,"Дет","ПСУ")))) AS тип, Станции2019.SNt
FROM (((Имена_станций LEFT JOIN Города ON Имена_станций.codegor = Города.code) INNER JOIN (Имена_областей INNER JOIN (Имена_ОЭС INNER JOIN (Станции2019 LEFT JOIN Доп_угли2019 ON (Станции2019.NUMB1120 = Доп_угли2019.NUMB1120) AND (Станции2019.YEAR = Доп_угли2019.YEAR)) ON Имена_ОЭС.oes = Станции2019.OES) ON Имена_областей.OBL = Станции2019.OBL) ON Имена_станций.NUMB = Станции2019.NUMB1120) LEFT JOIN имена_ГК ON Станции2019.GK = имена_ГК.code) LEFT JOIN имена_БЕ ON Станции2019.BE = имена_БЕ.code;
